mapper.select:
select o.*, c.name as customerName, c.phone as customerPhone,
       a.detail as addressDetail, a.tag as addressTag, a.lat as addressLat, a.lng as addressLng,
       a.name as addressName, a.phone as addressPhone, a.label as addressLabel,
       w.name as waterTypeName, w.spec as waterTypeSpec, w.price as waterTypePrice
from orders o
left join customer c on o.customer_id = c.id
left join address a on o.address_id = a.id
left join water_type w on o.water_type_id = w.id


        o.customer_id = #{customerId}


        and o.status = #{status}


        and a.tag = #{tag}


        and o.create_time >= #{createTimeStart}


        and o.create_time <= #{createTimeEnd}


order by o.create_time desc
